import{u as a,o as i,c as r,a2 as t}from"./chunks/framework.DZhUhjDB.js";const p=JSON.parse('{"title":"Cómo conseguí mi primer empleo en ciberseguridad","description":"Camino personal, certificaciones útiles y tips de entrevista","frontmatter":{"title":"Cómo conseguí mi primer empleo en ciberseguridad","description":"Camino personal, certificaciones útiles y tips de entrevista","author":"Equipo CDPN","date":"2026-07-06T00:00:00.000Z","tags":["carrera","certificaciones","empleo","entrevista"],"readingTime":"5 min"},"headers":[],"relativePath":"blog/06-primer-empleo.md","filePath":"blog/06-primer-empleo.md","lastUpdated":1787326374000}'),o={name:"blog/06-primer-empleo.md"},d=Object.assign(o,{setup(s){const{frontmatter:n}=a();return(l,e)=>(i(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="como-consegui-mi-primer-empleo-en-ciberseguridad" tabindex="-1">Cómo conseguí mi primer empleo en ciberseguridad <a class="header-anchor" href="#como-consegui-mi-primer-empleo-en-ciberseguridad" aria-label="Permalink to &quot;Cómo conseguí mi primer empleo en ciberseguridad&quot;">​</a></h1><div class="article-meta"><span class="accent">📝 Equipo CDPN</span><span>📅 6 Julio 2026</span><span>📖 5 min de lectura</span><span>🏷️ Carrera</span><span>🏷️ Empleo</span></div><h2 id="mi-camino" tabindex="-1">Mi camino <a class="header-anchor" href="#mi-camino" aria-label="Permalink to &quot;Mi camino&quot;">​</a></h2><p>No tuve un camino lineal. Empecé como técnico de sistemas, luego me especialicé en seguridad. Aquí comparto lo que me funcionó.</p><h2 id="lo-que-hice" tabindex="-1">Lo que hice <a class="header-anchor" href="#lo-que-hice" aria-label="Permalink to &quot;Lo que hice&quot;">​</a></h2><h3 id="_1-construi-un-portafolio" tabindex="-1">1. Construí un portafolio <a class="header-anchor" href="#_1-construi-un-portafolio" aria-label="Permalink to &quot;1. Construí un portafolio&quot;">​</a></h3><ul><li><strong>GitHub</strong> con proyectos de seguridad</li><li><strong>Blog</strong> con writeups de CTFs</li><li><strong>Labs</strong> documentados en TryHackMe/HTB</li></ul><h3 id="_2-obtuve-certificaciones" tabindex="-1">2. Obtuve certificaciones <a class="header-anchor" href="#_2-obtuve-certificaciones" aria-label="Permalink to &quot;2. Obtuve certificaciones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Certificación</th><th>Coste</th><th>Valor</th></tr></thead><tbody><tr><td>eJPT (INE)</td><td>~$200</td><td>⭐⭐⭐⭐ Entry-level</td></tr><tr><td>CompTIA Security+</td><td>~$350</td><td>⭐⭐⭐⭐ Ampliamente reconocida</td></tr><tr><td>CEH</td><td>~$1,200</td><td>⭐⭐⭐ En empresas tradicionales</td></tr><tr><td>OSCP</td><td>~$1,500+</td><td>⭐⭐⭐⭐⭐ El estándar de pentesting</td></tr></tbody></table><h3 id="_3-participe-en-la-comunidad" tabindex="-1">3. Participé en la comunidad <a class="header-anchor" href="#_3-participe-en-la-comunidad" aria-label="Permalink to &quot;3. Participé en la comunidad&quot;">​</a></h3><ul><li>Contribuí a proyectos open source</li><li>Hice bug bounty (HackerOne, Bugcrowd)</li><li>Asistí a eventos locales (OWASP chapters)</li></ul><h3 id="_4-me-prepare-para-entrevistas" tabindex="-1">4. Me preparé para entrevistas <a class="header-anchor" href="#_4-me-prepare-para-entrevistas" aria-label="Permalink to &quot;4. Me preparé para entrevistas&quot;">​</a></h3><ul><li><strong>Técnicas</strong>: Resolví retos en HackTheBox</li><li><strong>Teóricas</strong>: Estudié CIA, GDPR, OWASP Top 10</li><li><strong>Prácticas</strong>: Hice mock interviews</li></ul><h2 id="tips-de-entrevista" tabindex="-1">Tips de entrevista <a class="header-anchor" href="#tips-de-entrevista" aria-label="Permalink to &quot;Tips de entrevista&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Cuenta historias reales (lab work, CTFs)</span></span>
<span class="line"><span>2. Muestra tu portafolio (GitHub, blog)</span></span>
<span class="line"><span>3. Sé honesto sobre lo que no sabes</span></span>
<span class="line"><span>4. Pregunta sobre el stack de seguridad del equipo</span></span>
<span class="line"><span>5. Demuestra pasión por aprender</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="errores-que-cometi" tabindex="-1">Errores que cometí <a class="header-anchor" href="#errores-que-cometi" aria-label="Permalink to &quot;Errores que cometí&quot;">​</a></h2><ol><li><strong>No tener portafolio</strong> — Los reclutadores quieren ver tu trabajo</li><li><strong>Solo certificaciones</strong> — Sin práctica, no valen mucho</li><li><strong>No hacer networking</strong> — El 70% de los empleos son por referidos</li><li><strong>Miedo a aplicar</strong> — Si cumples el 60%, aplica</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El primer empleo en ciberseguridad no es fácil, pero es <strong>absolutamente posible</strong>. La clave es: portafolio + certificaciones + comunidad + constancia.</p><hr><p><em>Artículo publicado en el Blog CDPN — Semana 6</em></p>`,21)])]))}});export{p as __pageData,d as default};
